WITH cleaned AS (SELECT *, COALESCE(channel, 'unassigned') AS channel_filled, COALESCE(channel, 'UNKNOWN') AS resolved_channel FROM orders WHERE MONTH(order_date) IN (1, 5, 7) AND order_date >= DATE '2023-03-18'), with_last AS (SELECT s.*, latest.shipment_carrier FROM cleaned s LEFT JOIN LATERAL (SELECT c.carrier AS shipment_carrier FROM shipments c WHERE c.order_id = s.id ORDER BY c.shipped_date DESC, c.id DESC LIMIT 1) latest ON TRUE), remaining_keys AS (SELECT id, channel FROM with_last INTERSECT SELECT id, channel FROM orders WHERE customer_id IN (20, 23, 39)), reconciled AS (SELECT s.* FROM with_last s INNER JOIN remaining_keys k ON s.id = k.id AND s.channel = k.channel), with_window AS (SELECT a.*, pr.id AS promo_id, pr.promo_code, pr.discount_pct FROM reconciled a LEFT JOIN promotions pr ON a.channel <=> pr.channel AND a.order_date BETWEEN pr.starts_on AND pr.ends_on), base AS (SELECT id, customer_id, store_id, order_date, status, amount, shipping_fee, channel_filled, resolved_channel, shipment_carrier, promo_id, promo_code, discount_pct, discount_pct / NULLIF(discount, 0) AS discount_pct_per_discount FROM with_window WHERE shipment_carrier IS DISTINCT FROM 'UPS'), base_orders AS (SELECT *, COALESCE(shipment_carrier, 'N/A') AS shipment_carrier_filled FROM base WHERE order_date > DATE '2023-09-21' AND promo_code IN ('WELCOME5', 'VIP')) SELECT s.region, a.status, COUNT(*) AS cnt, SUM(a.promo_id) AS total_promo_id, MIN(a.shipping_fee) AS min_shipping_fee FROM base_orders a LEFT JOIN stores s ON a.store_id = s.id GROUP BY GROUPING SETS ((s.region, a.status), (s.region), ());
